import six
import sys


class UtilException(Exception):
    """Base exception for ute_common_util package."""


class MultipleSetupMethodsFound(UtilException):
    """ Exception is raised when more than one setup method is found."""


class MultipleTeardownMethodsFound(UtilException):
    """ Exception is raised when more than one teardown method is found."""


class SetupMethodNotFound(UtilException):
    """ Exception is raised when no setup method is implemented."""


class TeardownMethodNotFound(UtilException):
    """ Exception is raised when no setup method is implemented."""


class CommonResponsivenessException(Exception):
    """Main class for whole common_responsiveness package."""


class ProtocolError(CommonResponsivenessException):
    """Exception for Protocol operations."""


class PingError(ProtocolError):
    """Exception for Ping operations."""


class SshError(ProtocolError):
    """Exception for SSH operations."""


class HwApiError(ProtocolError):
    """Exception for HWAPI operations."""


def reraise_exception(new_exception_type):
    """Replaces generic Exception with given exception type."""
    new_exception_type.original_exc_type = sys.exc_info()[0]
    six.raise_from(new_exception_type, sys.exc_info()[1])
